#!/usr/bin/env node
/**
 * Sync the canonical design system (design/tokens.css + design/fonts/) into every
 * surface that ships it. relayne.org (static website/) and app.relayne.org
 * (Next.js saas/) deploy separately, so each needs its own served copy — this
 * script generates those copies from the one source of truth.
 *
 * Run `node scripts/sync-design.mjs` after editing design/tokens.css, then commit
 * the regenerated files. The saas build also runs it (package.json prebuild), so
 * the app can't ship stale tokens; the static site relies on the committed copy.
 *
 * Edit design/tokens.css, never the generated copies (they carry a header saying so).
 */
import { readFileSync, writeFileSync, copyFileSync, readdirSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repo = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(repo, 'design', 'tokens.css');
const fontsSrc = join(repo, 'design', 'fonts');

// Where the per-surface copies go. Each path is served at its domain's /... root.
const cssTargets = [
  join(repo, 'website', 'tokens.css'),
  join(repo, 'saas', 'app', 'tokens.css'),
];
const fontTargets = [
  join(repo, 'website', 'fonts'),
  join(repo, 'saas', 'public', 'fonts'),
];

const banner =
  '/* GENERATED by scripts/sync-design.mjs from design/tokens.css. DO NOT EDIT. */\n';
const tokens = readFileSync(src, 'utf8');
for (const t of cssTargets) {
  mkdirSync(dirname(t), { recursive: true });
  writeFileSync(t, banner + tokens);
  console.log('wrote', t.replace(repo + '/', ''));
}

const fonts = readdirSync(fontsSrc).filter((f) => f.endsWith('.woff2'));
for (const dir of fontTargets) {
  mkdirSync(dir, { recursive: true });
  for (const f of fonts) copyFileSync(join(fontsSrc, f), join(dir, f));
  console.log('copied', fonts.length, 'fonts →', dir.replace(repo + '/', ''));
}
console.log('design sync complete.');
